-- Durable per-step state and resumable intermediate results.
CREATE TABLE article_processing_steps (article_id BIGINT UNSIGNED NOT NULL, step_name VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'pending', worker_id VARCHAR(128) NULL, claim_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, attempt_count INT UNSIGNED NOT NULL DEFAULT 0, started_at DATETIME(6) NULL, heartbeat_at DATETIME(6) NULL, completed_at DATETIME(6) NULL, result_json JSON NULL, last_error VARCHAR(1000) NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (article_id, step_name), KEY idx_processing_steps_recovery (status, heartbeat_at), CONSTRAINT fk_processing_steps_article FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
